 private void neutral(){if(!foreground||!workflow.focused()||!workflow.workspace().equals("Fly")||!workflow.connectionLive()){message="Giữ focus trong Fly và dùng link mock hiện tại trước";return;}final long token=++neutralJob,connection=workflow.generation();workflow.input.focus(true,now());workflow.input.attach(connection,now());main.post(new Runnable(){public void run(){if(destroyed||!foreground||token!=neutralJob||!workflow.focused()||!workflow.workspace().equals("Fly")||connection!=workflow.generation()||!workflow.connectionLive())return;workflow.input.sample(workflow.session,connection,"mock:joystick",0,now());workflow.input.hold(true,now());main.postDelayed(this,60);}});message="Nguồn neutral/deadman mock đang giữ; không tự cấp owner";}
 private void selectClip(){stopPlayer("SOURCE_CHANGE");try(InputStream in=getAssets().open("synthetic.webm")){ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] chunk=new byte[4096];int n;while((n=in.read(chunk))!=-1){if(b.size()+n>1048576)throw new IOException("Fixture bound");b.write(chunk,0,n);}byte[] bytes=b.toByteArray();if(!Plan.hash(bytes).equals(BuildInfo.FIXTURE_SHA))throw new IOException("Fixture hash mismatch");workflow.video.select("SYNTHETIC_FIXTURE",BuildInfo.FIXTURE_SHA,bytes.length,now());message="Đã chọn clip tổng hợp; chưa phát";}catch(Exception e){message="Clip bị từ chối: "+e.getMessage();}}
 private void toggleVideo(){if(player!=null){stopPlayer("OPERATOR_STOPPED");message="Đã dừng playback mock";return;}if(!workflow.focused()||!workflow.workspace().equals("Fly")||!texture.isAvailable()||!workflow.video.selected){message="Chọn clip, giữ focus trong Fly trước";return;}try{final MediaPlayer mp=new MediaPlayer();player=mp;surface=new Surface(texture.getSurfaceTexture());mp.setSurface(surface);mp.setVolume(0,0);final long generation=workflow.video.prepare(now());try(AssetFileDescriptor fd=getAssets().openFd("synthetic.webm")){mp.setDataSource(fd.getFileDescriptor(),fd.getStartOffset(),fd.getLength());}
 mp.setOnPreparedListener(v->{if(player!=mp||generation!=workflow.video.generation)return;if(!workflow.focused()||!workflow.workspace().equals("Fly")||!workflow.video.prepared(generation,v.getVideoWidth(),v.getVideoHeight(),v.getDuration(),now())){stopPlayer("UNSUPPORTED_LOCAL_VIDEO");return;}if(workflow.video.play(generation,now())){texture.setAlpha(1);v.start();message="Playback clip mock; frame age native chưa biết";render();}});mp.setOnInfoListener((v,what,extra)->{if(player==mp&&generation==workflow.video.generation&&what==MediaPlayer.MEDIA_INFO_VIDEO_RENDERING_START)workflow.video.rendered(generation,now());return false;});mp.setOnCompletionListener(v->{if(player==mp&&generation==workflow.video.generation){workflow.video.ended(generation,now());releasePlayer();message="Clip mock kết thúc; không tự loop";render();}});mp.setOnErrorListener((v,a,b)->{if(player==mp){stopPlayer("DECODE_ERROR");message="Decoder lỗi; không kết luận đã render";render();}return true;});mp.prepareAsync();}catch(Exception e){stopPlayer("PLAYER_ERROR");message="Playback chưa khả dụng: "+e.getClass().getSimpleName();}}
 private void releasePlayer(){if(texture!=null)texture.setAlpha(0);MediaPlayer old=player;player=null;if(old!=null){old.setOnPreparedListener(null);old.setOnInfoListener(null);old.setOnCompletionListener(null);old.setOnErrorListener(null);old.release();}if(surface!=null){surface.release();surface=null;}}
 private void stopPlayer(String reason){workflow.video.stop(reason);releasePlayer();}
 private byte[] snapshot(){try{JSONObject o=new JSONObject(workflow.review());o.put("buildSourceId",BuildInfo.SOURCE_ID);o.put("compiledRaw",workflow.plan().compiledRaw);o.put("compiledMission",new JSONObject(workflow.plan().compiledRaw));o.put("capturedUTCMillis",System.currentTimeMillis());o.put("capturedElapsedMs",now());o.put("nativeRuntimeAttested",false);byte[] bytes=o.toString().getBytes(StandardCharsets.UTF_8);if(bytes.length>HistoryStore.MAX_BYTES)throw new IllegalStateException("Review byte bound");return bytes;}catch(JSONException e){throw new IllegalStateException(e);}}
 private void submit(Runnable r){if(busy){message="History I/O đang bận; thao tác lại sau";return;}busy=true;try{worker.execute(r);}catch(RejectedExecutionException e){busy=false;message="History queue đầy; chưa lưu/xuất";}}
 private void persist(){if(store==null){message="History không khả dụng; chưa lưu";return;}final byte[] bytes=snapshot();submit(()->{try{String hash=store.save(bytes);main.post(()->{busy=false;if(!destroyed){message="Đã lưu snapshot lịch sử "+hash.substring(0,12)+"; không restore quyền";render();}});}catch(Exception e){main.post(()->{busy=false;if(!destroyed){message="Chưa lưu: "+e.getMessage()+"; giữ file trước";render();}});}});}
 private void export(){if(busy){message="I/O đang bận";return;}pendingExport=snapshot();neutralJob++;stopPlayer("EXPORT_PICKER");Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/json");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_TITLE,"aeris-native29-mock-review.json");try{startActivityForResult(i,29);}catch(Exception e){pendingExport=null;message="Export picker không khả dụng";}}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=29)return;final byte[] bytes=pendingExport;pendingExport=null;if(result!=RESULT_OK||data==null||data.getData()==null||bytes==null){message="Không có snapshot/đích xuất; chuẩn bị lại";render();return;}final Uri uri=data.getData();if(!"content".equals(uri.getScheme())){message="Chỉ xuất content URI đã chọn";render();return;}submit(()->{try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("No provider stream");out.write(bytes);out.flush();main.post(()->{busy=false;if(!destroyed){message="Đã ghi JSON lịch sử; không phải bằng chứng drone thực";render();}});}catch(Exception e){main.post(()->{busy=false;if(!destroyed){message="Xuất có thể thiếu: giữ lỗi, không công bố hoàn chỉnh";render();}});}});}
 private void history(){if(store==null)return;submit(()->{try{ArrayList<String> labels=new ArrayList<>(),contents=new ArrayList<>();for(String hash:store.list()){try{String raw=new String(store.read(hash),StandardCharsets.UTF_8);JSONObject o=new JSONObject(raw);validateHistory(o);labels.add(hash.substring(0,12)+"  "+phaseLabel(o.optString("phase")));contents.add(raw);}catch(Exception e){labels.add(hash.substring(0,12)+"  Lỗi SHA/schema; giữ file");contents.add(null);}}main.post(()->{busy=false;if(destroyed)return;if(labels.isEmpty()){show("Lịch sử chỉ đọc","Chưa có snapshot đã lưu");return;}new AlertDialog.Builder(this).setTitle("Lịch sử chỉ đọc; không restore quyền").setItems(labels.toArray(new String[0]),(d,i)->{if(contents.get(i)==null){show("Snapshot bị từ chối","Giữ file lỗi; không công bố gói hoàn chỉnh");return;}show("Review lịch sử mock",contents.get(i));}).setNegativeButton("Đóng",null).show();});}catch(Exception e){main.post(()->{busy=false;if(!destroyed){message="History lỗi/bound; không restore";render();}});}});}
 private void validateHistory(JSONObject o)throws Exception{if(!o.optString("format").equals("aeris-native29-mock-review")||o.optInt("version")!=1||o.optBoolean("operational",true)||o.optBoolean("authorityRestorable",true))throw new IOException("History schema");String raw=o.getString("compiledRaw");if(!Plan.hash(raw).equals(o.getJSONObject("plan").getString("missionSha256")))throw new IOException("Compiled contract hash");JSONArray es=o.getJSONArray("events");if(es.length()>Workflow.MAX_EVENTS)throw new IOException("Event bound");String tail="";long last=-1;for(int i=0;i<es.length();i++){JSONObject e=es.getJSONObject(i);String canonical=e.getString("canonicalBody"),hash=e.getString("sha256");if(!Plan.hash(canonical).equals(hash))throw new IOException("Event SHA");JSONObject body=new JSONObject(canonical),view=e.getJSONObject("body");if(body.length()!=10||view.length()!=10||body.getInt("n")!=i+1||!tail.equals(body.getString("previousSha256"))||body.getLong("elapsedMs")<last)throw new IOException("Event sequence");for(String k:new String[]{"n","elapsedMs","generation","revision","cursor"})if(body.getLong(k)!=view.getLong(k))throw new IOException("Event numeric view");for(String k:new String[]{"session","planSha256","runId","kind","previousSha256"})if(!Objects.equals(body.opt(k),view.opt(k)))throw new IOException("Event view");last=body.getLong("elapsedMs");tail=hash;}if(!tail.equals(o.getString("eventChainTail")))throw new IOException("Chain tail");}
 private void show(String title,String value){ScrollView s=new ScrollView(this);s.addView(text(value,13,Color.WHITE));new AlertDialog.Builder(this).setTitle(title).setView(s).setPositiveButton("Đóng",(d,w)->{}).show();}
