 private final class RouteSurface extends View {private final Paint paint=new Paint(3);RouteSurface(){super(ShellActivity.this);setBackgroundColor(0xff15181c);}protected void onDraw(Canvas c){super.onDraw(c);double[][] poly=workflow.plan().polygon(),route=workflow.plan().route();float scale=Math.min(getWidth()/480f,getHeight()/330f),cx=getWidth()/2f,cy=getHeight()/2f;paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(dp(1));paint.setColor(0xff353b43);for(int x=0;x<getWidth();x+=dp(48))c.drawLine(x,0,x,getHeight(),paint);for(int y=0;y<getHeight();y+=dp(48))c.drawLine(0,y,getWidth(),y,paint);Path polygon=new Path();for(int i=0;i<poly.length;i++){float x=cx+(float)poly[i][0]*scale,y=cy-(float)poly[i][1]*scale;if(i==0)polygon.moveTo(x,y);else polygon.lineTo(x,y);}polygon.close();paint.setColor(0xffc7ced6);paint.setStrokeWidth(dp(2));c.drawPath(polygon,paint);paint.setStrokeWidth(dp(1));for(int i=1;i<route.length;i++)c.drawLine(cx+(float)route[i-1][0]*scale,cy-(float)route[i-1][1]*scale,cx+(float)route[i][0]*scale,cy-(float)route[i][1]*scale,paint);paint.setStyle(Paint.Style.FILL);paint.setColor(0xffefcd36);c.drawCircle(cx+(float)workflow.plan().homeX*scale,cy-(float)workflow.plan().homeY*scale,dp(4),paint);if(workflow.cursor()>0){double[] p=route[Math.min(workflow.cursor()-1,route.length-1)];c.drawCircle(cx+(float)p[0]*scale,cy-(float)p[1]*scale,dp(6),paint);}paint.setColor(0xffc7ced6);paint.setTextSize(dp(12));c.drawText("WGS84 / ENU mock • Home AMSL 10 m • flat SITL",dp(12),getHeight()-dp(16),paint);}}
